def extract_grid_from_text(text):
    """Extract grid rows from text that looks like space-separated numbers."""
    if not isinstance(text, str):
        return None

    # Split into chunks and look for grid-like patterns
    lines = text.split('\n')
    grids = []

    for i, line in enumerate(lines):
        # Check if this line starts a potential grid
        cells = []
        j = i
        while j < len(lines):
            cell_line = lines[j].strip()
            if not cell_line:
                break
            # Split by whitespace and check if all are integers
            parts = cell_line.split()
            if parts and all(p.isdigit() for p in parts):
                # Check if any part has more than 8 chars (likely part of a message, not grid)
                if len(parts) <= 10:  # Reasonable number of cells per row
                    try:
                        cells.append([int(x) for x in parts])
                    except ValueError:
                        break
                else:
                    # Too many cells, this is probably metadata
                    break
            else:
                break
            j += 1

        if cells:
            grids.append((i, cells))

    return grids

